+static bool
+sctp_vtag_match(uint32_t vtag1, uint32_t vtag2)
+{
+  /* If zero (unknown) tags match anything. Nonzero tags must be the same. */
+  if (vtag1 != 0) {
+    return (vtag1 == vtag2 || vtag2 == 0);
+  }
+  return true;
+}
